227	/// This struct is created by [`SliceExt::group_by_key`].
228	pub struct GroupByKey<'a, T, F> {
229	    slice: &'a [T],
230	    f: F,
231	}
232	
233	impl<'a, T, K, F> Iterator for GroupByKey<'a, T, F>
234	where
235	    F: FnMut(&T) -> K,
236	    K: PartialEq,
237	{
238	    type Item = (K, &'a [T]);
239	
240	    fn next(&mut self) -> Option<Self::Item> {
241	        let mut iter = self.slice.iter();
242	        let key = (self.f)(iter.next()?);
243	        let count = 1 + iter.take_while(|t| (self.f)(t) == key).count();
244	        let (head, tail) = self.slice.split_at(count);
245	        self.slice = tail;
246	        Some((key, head))
247	    }
248	}
