260	impl<I: Iterator + DoubleEndedIterator> MaybeReverseIter for I {
261	    type RevIfIter =
262	        Chain<Flatten<std::option::IntoIter<I>>, Flatten<std::option::IntoIter<Rev<I>>>>;
263	
264	    fn rev_if(self, condition: bool) -> Self::RevIfIter
265	    where
