484	            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
485	                self.to_possible_value()
486	                    .expect("no values are skipped")
487	                    .get_name()
488	                    .fmt(f)
489	            }
490	        }
